const VERSION='madero-v2-20261015-5';
const SHELL=['/index.html','/offline.html','/services.html','/booking.html','/styles.css','/app.js','/concierge.js','/install.js','/social.js','/manifest.webmanifest','/assets/logo.png','/assets/icon-192.png','/assets/icon-512.png','/assets/massage.webp','/assets/facial.webp','/assets/ritual.webp','/assets/spa.webp','/assets/madero.webp','/assets/reels/deep-detox.jpg','/assets/reels/extra-care.jpg','/assets/reels/lymphatic-madero.jpg'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(VERSION).then(cache=>cache.addAll(SHELL)))});
self.addEventListener('activate',event=>{event.waitUntil(Promise.all([caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith('madero-')&&key!==VERSION).map(key=>caches.delete(key)))),self.clients.claim()]))});
self.addEventListener('fetch',event=>{const req=event.request,url=new URL(req.url);if(req.method!=='GET'||url.origin!==self.location.origin||url.pathname.startsWith('/api/'))return;
 if(req.mode==='navigate'){event.respondWith((async()=>{const cache=await caches.open(VERSION);try{const response=await fetch(req);if(response.ok)await cache.put(url.pathname==='/'?'/index.html':url.pathname,response.clone());return response}catch{return (await cache.match(url.pathname==='/'?'/index.html':url.pathname))||(await cache.match('/offline.html'))}})());return}
 if(/\.(css|js|png|jpg|jpeg|webp|webmanifest|woff2)$/.test(url.pathname)){event.respondWith((async()=>{const cache=await caches.open(VERSION);const cached=await cache.match(req);const network=fetch(req).then(response=>{if(response.ok)cache.put(req,response.clone());return response});if(cached){event.waitUntil(network.catch(()=>{}));return cached}return network})())}
});
